'use strict';const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let session=null,state=null,selected=-1,lastVersion=-1,busy=false,pollTimer;
try{session=JSON.parse(sessionStorage.getItem('sakura-room')||'null')}catch{}
$('#code').value=new URL(location.href).searchParams.get('room')||'';
function persist(){sessionStorage.setItem('sakura-room',JSON.stringify(session))}
function tile(t,big=false,index=-1,indicator=false){const b=MJ.base(t),bonus=indicator?0:(MJ.isRed(t)?1:0)+(state?.match?.doras||[]).filter(d=>MJ.nextDora(d)===b).length;const content=b>=9&&b<27?tilePattern(b):b<9?'<span class="num">'+'一二三四五六七八九'[b%9]+'</span><span class="suit">萬</span>':b===31?'':'<span>'+esc(MJ.names[b])+'</span>';const suit=b<9?'man':b<18?'pin':b<27?'sou':b===32?'honor green':b===33?'honor red':b===31?'honor blank':'honor';return '<'+(big?'button':'span')+' class="tile '+(big?'big ':'mini ')+suit+' '+(indicator?'indicator ':'')+(bonus?'is-dora ':'')+(MJ.isRed(t)?'aka ':'')+(selected===index&&big?'selected':'')+'" '+(big?'data-tile="'+index+'"':'')+' aria-label="'+esc(MJ.names[t])+'" title="'+esc(MJ.names[t])+'">'+content+(bonus?'<span class="dora-badge">★'+(bonus>1?bonus:'')+'</span>':'')+'</'+(big?'button':'span')+'>'}
function melds(p){return p.melds.map(m=>'<span class="meld"><small>'+({chi:'チー',pon:'ポン',kan:m.open?'明槓':'暗槓'}[m.type]||'')+'</small>'+m.tiles.map((t,k)=>!m.open&&(k===0||k===3)?'<span class="tile mini back">◆</span>':tile(t)).join('')+'</span>').join('')}
function river(p){return p.river.map(r=>tile(r.t).replace('class="tile ','class="tile '+(r.taken?'taken ':'')+(r.riichi?'riichi-discard ':''))).join('')}
function portrait(p){return p.human?'<span class="online-human" role="img" aria-label="プレイヤー">'+esc(p.name.slice(0,1))+'</span>':'<span class="anime-portrait new-cast cast-'+p.characterId+' '+(p.riichi?'proud':p.score<10000?'worried':'normal')+'" role="img" aria-label="'+esc(p.name)+'"></span>'}
$('#characters').innerHTML=[['ハイデ','HEIDE','静かな眼差し'],['ラピス','LAPIS','蒼き魔法使い'],['キルケー','CIRCE','不敵な魔女']].map(([name,roman,tone],k)=>'<div class="character"><div class="portrait">'+portrait({name,characterId:k+1,score:25000})+'</div><div class="details"><small>'+roman+'</small><h3>'+name+'</h3><span class="personality">'+tone+'</span><p>空席にランダムで参加します。</p></div><span class="number">0'+(k+1)+'</span></div>').join('');
async function api(route,data){const r=await fetch('/api/'+route+(data?'':'?code='+session.code),{method:data?'POST':'GET',headers:{'Content-Type':'application/json',...(session?{Authorization:'Bearer '+session.token}:{})},...(data?{body:JSON.stringify({...data,code:data.code||session?.code})}:{})});const b=await r.json();if(!r.ok)throw Error(b.error||'通信に失敗しました');return b}
function showError(e){$('#error').textContent=e.message;$('#forget').hidden=!session}
function display(data){state=data;$('#entry').hidden=!!session;$('#room').hidden=!session||!!data.match;$('#lobby').hidden=!!data.match;$('.lobby-viewport').hidden=!!data.match;$('#game').hidden=!data.match;$('#room-code').textContent=data.code;$('#room-mode').textContent=data.mode===8?'半荘戦':'東風戦';$('#members').innerHTML=data.members.map(m=>'<div>'+esc(m.name)+(m.host?' · ルーム作成者':'')+(m.connected?'':' · 接続待ち')+'</div>').join('');$('#start').hidden=!data.host;$('#start').disabled=data.members.length<2;if(!data.match){requestAnimationFrame(()=>typeof fitViews==='function'&&fitViews());return}const g=data.match;if(g.version===lastVersion)return;lastVersion=g.version;selected=-1;const self=g.players[g.seat];$('#match-label').textContent=(g.mode===8?'半荘戦':'東風戦')+' · オンライン対戦';$('#room-label').textContent='ルーム '+data.code;$('#round').textContent='東南'[Math.floor(g.round/4)]+' '+(g.round%4+1)+' 局';$('#wall').textContent=g.remaining;$('#counters').textContent=g.honba+' 本場　供託 '+g.pot+' 本';
for(let relative=1;relative<4;relative++){const i=(g.seat+relative)%4,p=g.players[i],el=$('#seat'+relative);el.classList.toggle('active',g.turn===i&&g.phase!=='result');el.innerHTML='<div class="avatar">'+portrait(p)+'</div><div class="player-meta"><span class="wind">'+MJ.winds[(i-g.dealer+4)%4]+'</span>'+esc(p.name)+'<strong>'+p.score.toLocaleString()+'</strong><small>'+(p.riichi?'— リーチ —':(p.human?'プレイヤー':'CPU')+' · 手牌 '+p.handCount+'枚')+'</small></div><div class="melds opponent-melds">'+melds(p)+'</div>';$('#river'+relative).innerHTML=river(p)}
$('#dora').innerHTML=g.doras.map(t=>tile(t,false,-1,true)).join('');$('#speech').textContent=g.speech;$('#table-speech').textContent=g.speech;$('#status').textContent=g.finished?'対局終了':g.phase==='result'?'局終了：ルーム作成者の操作待ち':g.waiting?(g.waiting.seat===g.seat?'あなたの操作待ち':'操作待ち：'+g.players[g.waiting.seat].name):'対局が進行しています…';$('#self-score').textContent=self.score.toLocaleString();$('#self-wind').textContent=MJ.winds[(g.seat-g.dealer+4)%4];$('#self-riichi').textContent=self.riichi?'リーチ':'';$('#hand-info').textContent=self.riichi?'リーチ中':self.name+' · '+(self.melds.length?'副露中':'門前');$('#river0').innerHTML=river(self);let group=$('#self-melds');if(!group){group=document.createElement('div');group.id='self-melds';group.className='melds self-melds';$('#hand').insertAdjacentElement('afterend',group)}group.innerHTML=melds(self);$('#log').innerHTML=g.log.map(s=>'<div>'+esc(s)+'</div>').join('');drawHand();showResult(g);requestAnimationFrame(()=>typeof fitViews==='function'&&fitViews());}
function drawHand(){const g=state.match,l=g.actions;$('#hand').innerHTML=g.players[g.seat].hand.map((t,k)=>tile(t,true,k)).join('');document.querySelectorAll('[data-tile]').forEach(b=>{b.disabled=busy||!l.discard?.includes(+b.dataset.tile);b.onclick=()=>{const k=+b.dataset.tile;if(selected===k){sendAction({type:'discard',index:k});return}selected=k;drawHand()}});let buttons=[];const add=(label,type,index,extra={})=>buttons.push({label,type,index,...extra});if(l.discard){add('打牌','discard',selected);if(l.riichi?.includes(selected))add('リーチして打牌','discard',selected,{riichi:true});if(l.tsumo)add('ツモ','tsumo');for(const o of l.kans||[])add(o.label+' '+o.tiles.map(t=>MJ.names[t]).join(''),'kan',o.index)}if(l.ron)add('ロン','ron');for(const o of l.calls||[])add(o.label+' '+o.tiles.map(t=>MJ.names[t]).join(''),'call',o.index);if(l.pass)add('見送る','pass');if(l.next)add('次へ','next');$('#actions').innerHTML=buttons.map((b,k)=>'<button class="'+(['ron','tsumo','call','kan'].includes(b.type)?'accent':b.type==='pass'?'quiet':'primary')+'" data-action="'+k+'" '+(busy||b.type==='discard'&&selected<0?'disabled':'')+'>'+esc(b.label)+'</button>').join('');document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>sendAction(buttons[+b.dataset.action]));}
function showResult(g){const visible=!!g.result||g.finished;$('#result').hidden=!visible;if(!visible){if($('#modal').open)$('#modal').close();return}if(!$('#modal').open)$('#modal').showModal();if(g.finished){$('#result').innerHTML='<h2>対局終了</h2>'+g.players.slice().sort((a,b)=>b.score-a.score).map(p=>'<div class="result-row">'+esc(p.name)+'<b>'+p.score+'点</b></div>').join('')+'<p>次の対局はロビーで新しいルームを作成してください。</p><button id="new-room">ロビーへ</button>';$('#new-room').onclick=reset;return}if(!g.result)return;const r=g.result;$('#result').innerHTML='<h2>'+esc(r.type==='win'?g.players[r.winner].name+'の'+(r.winner===r.from?'ツモ':'ロン'):r.type==='nagashi'?'流し満貫':'流局')+'</h2>'+(r.hand?r.hand.map(t=>tile(t)).join(''):'')+(r.r?'<p class="yaku">'+r.r.yaku.map(([y,n])=>esc(y)+' '+n+'翻').join(' ／ ')+'</p>':'')+g.players.map((p,i)=>'<div class="result-row">'+esc(p.name)+'<b>'+(r.delta[i]>0?'+':'')+r.delta[i]+'点</b></div>').join('')+(g.actions.next?'<button id="result-next" class="primary">次へ →</button>':'<p>ルーム作成者の操作を待っています。</p>');if($('#result-next'))$('#result-next').onclick=()=>sendAction({type:'next'})}
async function sendAction(a){if(busy)return;busy=true;drawHand();try{const data=await api('action',{...a,version:state.match.version});$('#error').textContent='';display(data)}catch(e){showError(e)}finally{busy=false;if(state?.match)drawHand()}}
async function poll(){clearTimeout(pollTimer);if(!session)return;try{if(!busy){display(await api('state'));$('#error').textContent='';$('#forget').hidden=true}}catch(e){showError(e)}pollTimer=setTimeout(poll,700)}
for(const route of ['create','join'])$('#'+route).onclick=async()=>{try{const data=await api(route,{name:$('#name').value,mode:+$('#mode').value,code:route==='join'?$('#code').value.trim().toUpperCase():undefined});session={code:data.code,token:data.token};persist();display(data);poll()}catch(e){showError(e)}};
$('#start').onclick=async()=>{try{display(await api('start',{}))}catch(e){showError(e)}};$('#leave').onclick=async()=>{try{await api('leave',{});reset()}catch(e){showError(e)}};
$('#copy').onclick=async()=>{const link=location.origin+'/?room='+session.code;try{await navigator.clipboard.writeText(link);$('#copy').textContent='コピーしました'}catch{$('#error').textContent='招待URL：'+link}};
function reset(){clearTimeout(pollTimer);session=null;sessionStorage.removeItem('sakura-room');location.href='/'}$('#forget').onclick=reset;if(session)poll();

$('#online-help').onclick=()=>{alert('手牌を選んで打牌、または同じ牌をもう一度クリックします。45秒で自動打牌・見送りになります。次局への進行は作成者が行います。同じタブで再読み込みすると復帰できます。')};
$('#modal').addEventListener('cancel',e=>{if(state?.match?.result||state?.match?.finished)e.preventDefault()});
